export function roundPlan(playerCount: number): readonly Round[] {
  if (playerCount === 4) return ['Semifinal', 'Semifinal', 'Final'];
  if (playerCount === 8)
    return ['Quarterfinal', 'Quarterfinal', 'Quarterfinal', 'Quarterfinal', 'Semifinal', 'Semifinal', 'Final'];
  return [];
}

export function stageSize(round: Round): number {
  if (round === 'Quarterfinal') return 4;
  if (round === 'Semifinal') return 6;
  return 8;
}

export function createTournament(
  players: readonly TournamentPlayer[],
  boardCodes: readonly string[],
  createdAt: string,
): TournamentState | null {
  const plan = roundPlan(players.length);
  if (
    !plan.length ||
    players.some((player, index) => player.seed !== index + 1) ||
    !hasValidPlayerNames(players.map((player) => player.name)) ||
    !hasUniquePlayerNames(players.map((player) => player.name)) ||
    boardCodes.length !== plan.length ||
    new Set(boardCodes).size !== boardCodes.length
  )
    return null;

  if (
    boardCodes.some((code, index) => {
      const parsed = parseBoardCode(code);
      return !parsed || parsed.size !== stageSize(plan[index] ?? 'Final');
    })
  )
    return null;
  const opening: readonly (readonly number[])[] = players.length === 4
    ? [[1, 4], [2, 3]]
    : [[1, 8], [4, 5], [3, 6], [2, 7]];
  const openingCount = opening.length;
  const matches: TournamentMatch[] = plan.map((round, index) => {
    const isOpening = index < openingCount;
    const pair = opening[index];
    const playersForMatch: [number | null, number | null] = isOpening
      ? [pair?.[0] ?? null, pair?.[1] ?? null]
      : [null, null];
    const playerSlot: 0 | 1 = index % 2 === 0 ? 0 : 1;
    const laterPlayerSlot: 0 | 1 = index === openingCount ? 0 : 1;
    const next = index === plan.length - 1
      ? null
      : index < openingCount
        ? {
            matchIndex: players.length === 4 ? 2 : 4 + Math.floor(index / 2),
            playerSlot,
          }
        : { matchIndex: plan.length - 1, playerSlot: laterPlayerSlot };
    return {
      boardCode: boardCodes[index] ?? '',
      next,
      players: playersForMatch,
      results: [null, null],
      round,
      winnerSeed: null,
    };
  });
  return {
    activePlayer: 0,
    championSeed: null,
    completedAt: null,
    createdAt,
    currentGame: null,
    currentMatchIndex: 0,
    matches,
    phase: 'ready',
    playerCount: players.length === 4 ? 4 : 8,
    players,
  };
}

export function beginTournamentTurn(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'ready' && tournament.phase !== 'betweenTurns') return tournament;
  return { ...tournament, currentGame: null, phase: 'playing' };
}

export function advanceTournamentMatch(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'betweenMatches') return tournament;
  return {
    ...tournament,
    activePlayer: 0,
    currentGame: null,
    currentMatchIndex: tournament.currentMatchIndex + 1,
    phase: 'ready',
  };
}

export function finishTournamentTurn(
  tournament: TournamentState,
  result: TurnResult,
  completedAt: string,
): TournamentState {
  if (tournament.phase !== 'playing' || !isValidTurnResult(result, tournament.matches[tournament.currentMatchIndex]?.round))
    return tournament;
  const index = tournament.currentMatchIndex;
  const match = tournament.matches[index];
  if (!match || match.players[tournament.activePlayer] === null) return tournament;
  const results: [TurnResult | null, TurnResult | null] = [match.results[0], match.results[1]];
  results[tournament.activePlayer] = result;
  if (tournament.activePlayer === 0) {
    return {
      ...tournament,
      activePlayer: 1,
      currentGame: null,
      matches: replaceMatch(tournament.matches, index, { ...match, results }),
      phase: 'betweenTurns',
    };
  }

  const firstSeed = match.players[0];
  const secondSeed = match.players[1];
  const firstResult = results[0];
  const secondResult = results[1];
  if (firstSeed === null || secondSeed === null || !firstResult || !secondResult) return tournament;
  const winnerSeed = compareTournamentResults(firstResult, firstSeed, secondResult, secondSeed) <= 0
    ? firstSeed
    : secondSeed;
  const finishedMatch = { ...match, results, winnerSeed };
  const matches = [...replaceMatch(tournament.matches, index, finishedMatch)];
  if (match.next) {
    const nextMatch = matches[match.next.matchIndex];
    if (!nextMatch) return tournament;
    const nextPlayers: [number | null, number | null] = [
      nextMatch.players[0],
      nextMatch.players[1],
    ];
    nextPlayers[match.next.playerSlot] = winnerSeed;
    matches[match.next.matchIndex] = { ...nextMatch, players: nextPlayers };
    return {
      ...tournament,
      activePlayer: 0,
      currentGame: null,
      matches,
      phase: 'betweenMatches',
    };
  }
  return {
    ...tournament,
    championSeed: winnerSeed,
    completedAt,
    currentGame: null,
    matches,
    phase: 'complete',
  };
}

export function compareTournamentResults(
  first: TurnResult,
  firstSeed: number,
  second: TurnResult,
  secondSeed: number,
): number {
  return first.moves - second.moves || first.elapsedMs - second.elapsedMs || firstSeed - secondSeed;
}

export function tournamentPlayer(tournament: TournamentState, seed: number | null): TournamentPlayer | null {
  return seed === null ? null : tournament.players[seed - 1] ?? null;
}

function isValidTurnResult(result: TurnResult, round: Round | undefined): boolean {
  return (
    round !== undefined &&
    Number.isSafeInteger(result.moves) &&
    result.moves >= stageSize(round) ** 2 / 2 &&
    result.moves <= MOVES_MAX &&
    Number.isFinite(result.elapsedMs) &&
    result.elapsedMs >= 0 &&
    result.elapsedMs <= ELAPSED_MAX_MS
  );
}

function replaceMatch(
  matches: readonly TournamentMatch[],
  index: number,
  match: TournamentMatch,
): TournamentMatch[] {
  return matches.map((entry, position) => (position === index ? match : entry));
}
export function normalizePlayerName(draft: string): string {
  return draft.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function hasValidPlayerNames(names: readonly string[]): boolean {
  return names.every((name) => {
    const length = Array.from(name).length;
    return length >= 2 && length <= 20 && normalizePlayerName(name) === name;
  });
}

export function hasUniquePlayerNames(names: readonly string[]): boolean {
  const seen = new Set<string>();
  for (const name of names) {
    const comparison = name.toLowerCase();
    if (seen.has(comparison)) return false;
    seen.add(comparison);
  }
  return true;
}
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { validateTournamentState } from './validate-state.ts';
import type { TournamentState } from './types.ts';

const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
const TOURNAMENT_VERSION = 1;
const TOURNAMENT_TEXT_MAX_BYTES = 65_536;

type TournamentDecode =
  | { readonly ok: true; readonly tournament: TournamentState }
  | { readonly ok: false; readonly message: string };

export function encodeTournament(tournament: TournamentState, currentGame: string | null): string {
  const data = { ...tournament, currentGame };
  const validation = validateTournamentState(data);
  if (!('state' in validation)) throw new Error('Cannot export an invalid tournament.');
  return JSON.stringify(
    sortKeys({ format: TOURNAMENT_FORMAT, tournament: data, version: TOURNAMENT_VERSION }),
    null,
    2,
  );
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (typeof value !== 'object' || value === null) return value;
  return Object.fromEntries(
    Object.entries(value).sort(([first], [second]) => first.localeCompare(second))
      .map(([key, entry]) => [key, sortKeys(entry)]),
  );
}

export function decodeTournament(text: string): TournamentDecode {
  if (text.length > TOURNAMENT_TEXT_MAX_BYTES || !isWithinBytes(text, TOURNAMENT_TEXT_MAX_BYTES))
    return { ok: false, message: 'Invalid tournament.' };
  const value = parseJson(text);
  try {
    const envelope = objectWithKeys(value, ['format', 'tournament', 'version']);
    if (!envelope) return { ok: false, message: 'Invalid tournament.' };
    if (envelope.format !== TOURNAMENT_FORMAT || envelope.version !== TOURNAMENT_VERSION)
      return { ok: false, message: 'Invalid tournament.' };
    const result = validateTournamentState(envelope.tournament);
    return 'state' in result
      ? { ok: true, tournament: result.state }
      : { ok: false, message: result.message };
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : 'Invalid tournament.' };
  }
}

function objectWithKeys(value: unknown, keys: readonly string[]): Record<string, unknown> | null {
  if (!isJsonObject(value)) return null;
  const record = value;
  const unknown = Object.keys(record).find((key) => !keys.includes(key));
  if (unknown) throw new Error(`Unknown field: ${unknown}.`);
  return hasExactKeys(record, keys) ? record : null;
}
import { isJsonObject, parseJson } from '../saved-format.ts';
import { validateTournamentState } from './validate-state.ts';
import type { TournamentState } from './types.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const TOURNAMENT_RETENTION = 10;
export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export function readTournaments(store: TournamentStore | null): {
  readonly items: readonly TournamentState[];
  readonly available: boolean;
} {
  if (!store) return { items: [], available: false };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (!text) return { items: [], available: true };
    const value = parseJson(text);
    if (!isJsonObject(value) || Object.keys(value).length !== 2 || value.v !== 3 || !Array.isArray(value.items))
      return { items: [], available: true };
    const items: TournamentState[] = [];
    for (const item of value.items) {
      const result = validateTournamentState(item);
      if (!('state' in result) || result.state.phase !== 'complete') return { items: [], available: true };
      items.push(result.state);
    }
    return { items: retainTournaments(items), available: true };
  } catch {
    return { items: [], available: false };
  }
}

export function writeTournaments(
  store: TournamentStore | null,
  items: readonly TournamentState[],
): { readonly success: boolean } {
  if (!store) return { success: false };
  try {
    store.setItem(TOURNAMENTS_KEY, JSON.stringify({ v: 3, items: retainTournaments(items) }));
    return { success: true };
  } catch {
    return { success: false };
  }
}

export function retainTournaments(items: readonly TournamentState[]): TournamentState[] {
  const unique = new Map(items.map((item) => [JSON.stringify(item), item]));
  return [...unique.values()]
    .sort((first, second) => (second.completedAt ?? '').localeCompare(first.completedAt ?? ''))
    .slice(0, TOURNAMENT_RETENTION);
}
