        active={!tournamentOpen}
        status={status}
        tournamentButtonRef={tournamentButton}
        announce={announce}
        openTournament={() => setTournamentOpen(true)}
      />
      {tournamentOpen && (
        <TournamentScreen
          status={status}
          announce={announce}
          onBack={() => setTournamentOpen(false)}
        />
      )}
    </main>
  );
