import assert from 'node:assert/strict';
import { expect, test, TestTimeouts } from './browser-test.ts';
import { PREFERENCES_KEY } from '../src/game/session/storage.ts';
import type { Page } from '@playwright/test';

async function finishTournamentBoard(page: Page): Promise<void> {
  const cards = page.locator('.tournament-current .card');
  const count = await cards.count();
  const unseen = new Set(Array.from({ length: count }, (_, index) => index));
  const known = new Map<string, number[]>();
  const matched = new Set<number>();

  async function faceAt(index: number): Promise<string> {
    const card = cards.nth(index);
    const label = await card.getAttribute('aria-label');
    const face = label?.match(/^Row \d+, column \d+, (?:revealed|matched), (.+)$/)?.[1];
    if (!face)
      throw new Error(
        `Expected card ${index} to be revealed; got ${label}. ` +
          `Tracked matches: ${[...matched].join(', ')}. Remembered: ${JSON.stringify([...known])}.`,
      );
    return face;
  }

  async function match(first: number, second: number): Promise<void> {
    await cards.nth(first).click();
    await cards.nth(second).click();
    await expect(cards.nth(first)).toHaveClass(/matched/);
    matched.add(first);
    matched.add(second);
  }

  while (matched.size < count) {
    if (unseen.size === 0) {
      const pair = [...known.entries()].find(([, positions]) => positions.length === 2);
      if (!pair) throw new Error('Expected the remembered faces to contain a pair.');
      const positions = pair[1];
      const first = positions[0];
      const second = positions[1];
      if (first === undefined || second === undefined) throw new Error('Missing remembered position.');
      await match(first, second);
      known.delete(pair[0]);
      continue;
    }

    const first = unseen.values().next().value;
    if (first === undefined) throw new Error('Expected an unrevealed card.');
    unseen.delete(first);
    await cards.nth(first).click();
    const firstFace = await faceAt(first);
    const remembered = known.get(firstFace)?.find((position) => position !== first);
    if (remembered !== undefined) {
      await cards.nth(remembered).click();
      await expect(cards.nth(first)).toHaveClass(/matched/);
      matched.add(first);
      matched.add(remembered);
      known.delete(firstFace);
      continue;
    }

    const second = unseen.values().next().value;
    if (second === undefined) throw new Error('Expected a second unrevealed card.');
    unseen.delete(second);
    await cards.nth(second).click();
    const secondFace = await faceAt(second);
    if (firstFace === secondFace) {
      await expect(cards.nth(first)).toHaveClass(/matched/);
      matched.add(first);
      matched.add(second);
    } else {
      known.set(firstFace, [...(known.get(firstFace) ?? []), first]);
      known.set(secondFace, [...(known.get(secondFace) ?? []), second]);
      await page.clock.runFor(800);
    }
  }
  await expect(cards).toHaveCount(count);
  await expect(page.locator('.tournament-current .card.matched')).toHaveCount(count);
}

test(
  'four-player tournament uses shared deals, exports and reloads its champion history',
  async ({ page, gameURL }) => {
    const preferences = { schemaVersion: 1, size: 10, bestMoves: { '4': 8 } };
    await page.addInitScript(
      ({ key, value }) => localStorage.setItem(key, JSON.stringify(value)),
      { key: PREFERENCES_KEY, value: preferences },
    );
    await page.clock.install();
    await page.goto(gameURL);
    await page.getByRole('button', { name: 'Tournament', exact: true }).click();
    await expect(page.getByRole('heading', { name: 'Tournament', level: 2 })).toBeFocused();
    for (const [index, name] of ['Ada', 'Bo', 'Cora', 'Dev'].entries())
      await page.getByLabel(`Player ${index + 1}`, { exact: true }).fill(name);
    await page.getByRole('button', { name: 'Start tournament', exact: true }).click();

    for (let match = 0; match < 3; match += 1) {
      await page.getByRole('button', { name: 'Start turn', exact: true }).click();
      if (match === 0) {
        await page.getByRole('button', { name: 'Export tournament', exact: true }).click();
        const draft = await page.locator('#tournament-json').inputValue();
        assert.match(draft, /"format": "neon-pairs\/tournament"/);
        await page.getByRole('button', { name: 'Load tournament', exact: true }).click();
      }
      await finishTournamentBoard(page);
      await expect(page.getByRole('button', { name: 'Next turn', exact: true })).toBeVisible();
      await page.getByRole('button', { name: 'Next turn', exact: true }).click();
      await finishTournamentBoard(page);
      if (match < 2) {
        await expect(page.getByRole('button', { name: 'Next match', exact: true })).toBeVisible();
        await page.getByRole('button', { name: 'Next match', exact: true }).click();
      }
    }

    const champion = page.locator('.tournament-current h3').filter({ hasText: /^Champion:/ });
    await expect(champion).toBeVisible();
    await expect(page.getByRole('button', { name: 'Back to game', exact: true })).toBeVisible();
    await page.getByRole('button', { name: 'Export tournament', exact: true }).click();
    const exported = await page.locator('#tournament-json').inputValue();
    await page.getByRole('button', { name: 'Load tournament', exact: true }).click();
    await expect(champion).toBeVisible();
    await expect(page.locator('.tournament-history summary')).toContainText('Champion:');
    const savedPreferences = await page.evaluate((key) => localStorage.getItem(key), PREFERENCES_KEY);
    assert.deepEqual(JSON.parse(savedPreferences ?? 'null'), preferences);

    await page.reload();
    await expect(page.locator('.card')).toHaveCount(100);
    await page.getByRole('button', { name: 'Tournament', exact: true }).click();
    await expect(page.locator('.tournament-history summary')).toContainText('Champion:');
    await expect(page.locator('#tournament-json')).toHaveValue('');
    assert.match(exported, /"championSeed":/);
  },
  {},
  undefined,
  TestTimeouts.long,
);

